<?php
need_admin();
if(isset($_GET['backup']))fail(400,'Use the separate authorised backup download link.');
heading('ADMINISTRATION','Updates','Install a new release from a ZIP or directly from the MustrHQ GitHub repository.');
echo '<div class="notice">Installed version: <strong>'.e(APP_VERSION).'</strong> · Database schema: '.e(setting('schema_version')).' · Repository: <a href="https://github.com/'.e(APP_REPO).'" target="_blank" rel="noopener">'.e(APP_REPO).'</a></div>';
if(is_file(ROOT.'/private/maintenance.json'))echo '<div class="notice danger">Maintenance is enabled. Read private/maintenance.json with your hosting administrator and recover from the private backup before reopening the kitchen portal.</div>';
if(!class_exists('ZipArchive'))echo '<div class="notice danger">Enable the PHP zip extension before installing updates.</div>';
echo '<div class="entry-grid"><section class="card"><h2>Upload a release ZIP</h2><p class="muted">Use a built Kitchen Safety release package. A backup is created before files are replaced. Configuration and kitchen records are preserved.</p><form method="post" enctype="multipart/form-data">'.csrf().'<input type="hidden" name="action" value="update_upload"><label class="field"><span>Release package</span><input type="file" name="package" accept=".zip,application/zip" required><small>Maximum 32 MiB; the server upload limit also applies.</small></label>';button('Check and stage ZIP');echo '</form></section><section class="card"><h2>Update from GitHub</h2><p class="muted">Check the latest stable release. The release ZIP is downloaded over HTTPS and checked against GitHub’s SHA-256 digest.</p>';form_start('update_check');button('Check latest version');echo '</form>';
$r=$_SESSION['github_release']??null;if($r){echo '<hr><p><strong>Latest release: '.e($r['version']).'</strong></p><p class="help">Published '.e($r['published_at']).'</p><pre>'.e($r['notes']).'</pre>';if(version_compare($r['version'],APP_VERSION,'>')){form_start('update_github');button('Download and stage update');echo '</form>';}else echo '<p class="notice success">Your installation is up to date.</p>';}
echo '</section></div>';
if($p=staged_plan()){
 echo '<section class="card"><p class="eyebrow">READY TO INSTALL</p><h2>Version '.e($p['version']).'</h2><p>'.(int)$p['files'].' verified files · Source: '.e($p['source']).' · Target schema '.(int)$p['schema'].'</p><p class="help">The kitchen screens pause briefly during installation. A private backup includes the database and affected existing files. File replacement errors trigger rollback. If a database migration fails, maintenance stays enabled for manual recovery.</p>';form_start('update_apply');echo '<label class="checkline"><input type="checkbox" name="confirm" required> Install this trusted release now.</label>';button('Back up and install update');echo '</form>';form_start('update_cancel');button('Discard staged update','');echo '</form></section>';
}
echo '<section class="card"><h2>Update history</h2>';$history=arr(setting('update_history','[]'));if(!$history)echo '<p class="muted">No updates have been installed through this panel yet.</p>';foreach(array_reverse($history) as $h)echo '<article class="review-note"><strong>'.e($h['from']).' → '.e($h['version']).'</strong><p>'.e($h['source']).' · '.e($h['by']).' · '.e($h['at']).' UTC</p><a class="btn small" href="'.e(base_url('admin/backup.php?id='.$h['backup'])).'">Download private backup</a></article>';echo '</section>';
